@extends('layouts.hris')
@section('title', 'Statement of Assets, Liabilities and Net Worth')
@section('subtitle', 'Maintain private SALN working records and exact declared totals.')
@section('actions')<button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#saln-modal">New filing</button>@endsection
@section('content')
<div class="alert alert-info">Electronic submission is not enabled until the filing, revision, and signatory policy is approved. These records remain editable working copies.</div>
<x-hris.table id="saln-table" endpoint="/saln/data" :columns="[['key'=>'employee.name','label'=>'Declarant'],['key'=>'compliance_date','label'=>'As of'],['key'=>'total_assets','label'=>'Assets'],['key'=>'total_liabilities','label'=>'Liabilities'],['key'=>'net_worth','label'=>'Net worth']]" :actions="[['name'=>'details','label'=>'Open']]"/>
<x-hris.modal id="saln-modal" title="Create SALN working copy"><form id="saln-form" data-endpoint="/saln"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none"></div><div class="row g-3"><x-hris.field name="filing_type" type="select" :options="[1=>'Annual',2=>'Assumption',3=>'Separation']" required/><x-hris.field name="compliance_type" type="select" :options="[1=>'Joint',2=>'Separate',3=>'Not applicable']" required/><x-hris.field name="compliance_date" type="date" required/></div></div><div class="modal-footer"><button class="btn btn-primary">Create working copy</button></div></form></x-hris.modal>
<x-hris.modal id="saln-work-modal" title="SALN sections"><div class="modal-body"><div id="saln-summary" class="mb-4"></div><form id="saln-entry-form"><div data-form-errors class="alert alert-danger d-none"></div><div class="row g-3"><x-hris.field name="section" type="select" :options="['declarant'=>'Declarant and spouse','children'=>'Unmarried children','real_property'=>'Real property','personal_property'=>'Personal property','liability'=>'Liability','business_interest'=>'Business interest','government_relative'=>'Relative in government']" required/><x-hris.field name="declared_amount" label="Declared amount (property / liability only)" type="number" min="0" step="0.01"/><x-hris.field name="details_text" class="col-12" type="textarea" label="Section details" help="Enter one field per line as label: value. Examples: description: House; location: Manila." required/></div><div class="mt-3"><button class="btn btn-primary">Add section entry</button></div></form></div><div class="modal-footer"><a id="print-saln" class="btn btn-outline-secondary" target="_blank">Print working copy</a></div></x-hris.modal>
@endsection
@push('scripts')<script>document.addEventListener('hris:ready',()=>{const table=document.querySelector('#saln-table'),entry=document.querySelector('#saln-entry-form');let current=null;function render(detail){const box=document.querySelector('#saln-summary');box.replaceChildren();const totals=document.createElement('p');totals.className='fw-semibold';totals.textContent=`Assets: ${detail.total_assets} - Liabilities: ${detail.total_liabilities} - Net worth: ${detail.net_worth}`;box.append(totals);(detail.entries||[]).forEach(item=>{const row=document.createElement('div');row.className='border rounded p-2 mb-2';row.textContent=`${item.section.replaceAll('_',' ')}: ${Object.values(item.data).join('; ')}${item.declared_amount?' - '+item.declared_amount:''}`;box.append(row)})}async function open(row){current=row;const detail=await HRIS.request(`/saln/${row.id}`);render(detail);entry.dataset.endpoint=`/saln/${row.id}/entries`;document.querySelector('#print-saln').href=`/saln/${row.id}/print`;HRIS.openModal('saln-work-modal')}HRIS.bindForm(document.querySelector('#saln-form'),{success:(result)=>{table.table.load();setTimeout(()=>open({id:result.id}),250)}});HRIS.bindForm(entry,{keepOpen:true,prepare:b=>{b.data={};String(b.details_text||'').split(/\n/).forEach(line=>{const split=line.indexOf(':');if(split>0)b.data[line.slice(0,split).trim().toLowerCase().replaceAll(' ','_')]=line.slice(split+1).trim()});delete b.details_text},success:async()=>{render(await HRIS.request(`/saln/${current.id}`));table.table.load();entry.reset()}});table.addEventListener('table:action',async({detail:{row}})=>{try{await open(row)}catch(e){HRIS.feedback(e.message,true)}})});</script>@endpush
